import{_ as r,o as t,c as p,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Brazilian Government Case - Brenno Martinez, Serpro","description":"","frontmatter":{"title":"Brazilian Government Case - Brenno Martinez, Serpro","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Brazil","OpenStack","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Brazilian_Government_Case_-_Brenno_Martinez_Serpro.md","filePath":"posts/2019/Brazilian_Government_Case_-_Brenno_Martinez_Serpro.md","lastUpdated":1780459816000}'),i={name:"posts/2019/Brazilian_Government_Case_-_Brenno_Martinez_Serpro.md"};function a(o,e,l,_,s,C){return t(),p("div",null,[...e[0]||(e[0]=[n("<p>会议纪要</p><p>会议时间：[请填写具体日期和时间] 会议地点：[请填写会议地点] 参会人员：Brenda Martinez（自力更生工场代表）</p><p>会议主题：自力更生工场在巴西政府项目中的Ceph使用经验分享</p><p>会议内容：</p><p>一、背景介绍 自力更生工场是巴西政府下属的IT公司，提供公共机构和巴西公民的解决方案。公司拥有自己的数据中心，并开发了基于OpenStack、Kubernetes等技术的云解决方案“estelí”。</p><p>二、Ceph使用历程</p><ol><li>自2017年初，自力更生工场使用Ceph对象存储存储巴西驾驶执照数据，已有超过6000万份驾驶执照。</li><li>首次使用Ceph时，由于预算限制，没有购买新的硬件。</li><li>在测试阶段，Ceph集群出现性能问题，包括操作缓慢、OSD频繁上下线和Keystone服务不稳定。</li></ol><p>三、问题分析与解决方案</p><ol><li>发现性能问题的原因是个别桶中存储了过多的对象（数千万）。</li><li>解决方案包括：限制每个桶的对象数量、增加Keystone服务器数量、优化代码以复用令牌、升级硬件和软件版本。</li></ol><p>四、Ceph应用现状</p><ol><li>Ceph为巴西驾驶执照提供对象存储服务，确保数据安全。</li><li>Ceph为云解决方案中的容器提供块和文件系统存储服务。</li><li>Ceph将很快为Hadoop集群提供存储服务。</li><li>正在实施多站点环境。</li></ol><p>五、总结 自力更生工场在Ceph的使用过程中遇到挑战，但通过优化和升级硬件，成功解决了性能问题。Ceph已成为其存储解决方案的重要组成部分。</p><p>后续行动计划：</p><ol><li>持续优化Ceph集群性能，确保稳定运行。</li><li>推广Ceph在更多领域的应用，如大数据、人工智能等。</li><li>与Ceph社区保持紧密合作，共同推动Ceph技术的发展。</li></ol>",14)])])}const c=r(i,[["render",a]]);export{h as __pageData,c as default};
